import streamlit as stimport pandas as pdimport joblib# Load trained modelmodel = joblib.load('salary_prediction_model.pkl')# App titlest.title("Salary Prediction Web App")st.write("Enter years of experience to predict salary")# User inputexperience = st.number_input(    "Years of Experience",    min_value=0.0,    max_value=50.0,    step=0.5)# Predict buttonif st.button("Predict Salary"):    input_data = pd.DataFrame({        'Years of Experience': [experience]    })    prediction = model.predict(input_data)    st.success(f"Predicted Salary: {prediction[0]:.2f}")